import httpx

async def generate(ctx, api):
    BASE = "https://autodl.art/api/v1"
    WORKFLOW_ID = "minimax_h3_lightx2v_no_pic"
    API_KEY = ctx.get("api_key") or "3jfV2WXEzzGkSW1gcuZwAtTAMbDhruqwgphMu9mXQ5EIKapd"
    headers = {"Authorization": API_KEY, "Content-Type": "application/json"}

    _RES_MAP = {
        "480p": "480p竖", "720p": "720p竖", "1080p": "1080p竖",
        "480p竖": "480p竖", "480p横": "480p横",
        "720p竖": "720p竖", "720p横": "720p横",
        "1080p竖": "1080p竖", "1080p横": "1080p横",
    }

    dyn = ctx.get("dynamic_inputs") or {}
    prompt = (ctx.get("prompt") or "").strip()
    task_id = (ctx.get("task_id") or dyn.get("task_id") or "").strip()

    # —— 查询模式（秒回，不许 sleep）——
    if task_id and not prompt:
        async with httpx.AsyncClient(timeout=15) as client:
            r = await client.get(f"{BASE}/comfyui/comfyui_workflow/result/{task_id}", headers=headers)
            r.raise_for_status()
            data = (r.json() or {}).get("data", {}) or {}
            status = str(data.get("status") or "").upper()
            url = None
            for item in (data.get("results") or []):
                if isinstance(item, dict) and item.get("type") == "video" and item.get("url"):
                    url = item["url"]
                    break
            if not url and data.get("results"):
                first = data["results"][0]
                url = first.get("url") if isinstance(first, dict) else (first if isinstance(first, str) else None)
            if url:
                return {"video_url": url, "status": data.get("status"), "task_id": task_id}
            if status in ("FAILED", "ERROR", "FAIL", "CANCELLED"):
                raise RuntimeError(f"AutoDL 任务失败 task_id={task_id}: {str(data)[:300]}")
            return {"video_url": None, "status": data.get("status") or "QUEUED", "task_id": task_id}

    if not prompt:
        raise ValueError("缺少 prompt")

    try:
        duration = max(3, min(10, int(ctx.get("duration") or 5)))
    except (ValueError, TypeError):
        duration = 5
    body = {
        "prompt": prompt,
        "duration": duration,
        "resolution": _RES_MAP.get(ctx.get("resolution") or "480p竖", "480p竖"),
    }

    # 首帧/参考图/尾帧 → ref_image_0..8（保序去重；仅公网 http(s)）
    ordered = []
    for k in ("first_frame", "first_frame_url"):
        v = ctx.get(k) or dyn.get(k)
        if isinstance(v, str) and v.startswith(("http://", "https://", "data:")):
            ordered.append(v)
            break
    for u in (ctx.get("reference_images") or dyn.get("reference_images") or []):
        if isinstance(u, str) and u.startswith("http"):
            ordered.append(u)
    for k in ("last_frame", "last_frame_url"):
        v = ctx.get(k) or dyn.get(k)
        if isinstance(v, str) and v.startswith(("http://", "https://", "data:")):
            ordered.append(v)
            break
    seen, uniq = set(), []
    for u in ordered:
        if u not in seen:
            seen.add(u)
            uniq.append(u)
    for i, u in enumerate(uniq[:9]):
        body[f"ref_image_{i}"] = u

    # —— 提交即返（不许轮询：外层 40s 即超时，框架后台轮询接管）——
    async with httpx.AsyncClient(timeout=20) as client:
        r = await client.post(f"{BASE}/comfyui/comfyui_workflow/{WORKFLOW_ID}", json=body, headers=headers)
        r.raise_for_status()
        resp = r.json() or {}
        if resp.get("code") not in (None, "Success", "success"):
            raise RuntimeError(f"AutoDL 提交失败: {str(resp)[:400]}")
        new_id = (resp.get("data") or {}).get("task_id")
        if not new_id:
            raise RuntimeError(f"AutoDL 未返回 task_id: {str(resp)[:400]}")
        return {"video_url": None, "task_id": new_id, "status": "SUBMITTED"}
